// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.orchestratorimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.brain.context.Turnimport com.roshan.persona.brain.memory.Memoryimport com.roshan.persona.brain.memory.MemoryInterfaceimport com.roshan.persona.brain.memory.MemoryTypeimport com.roshan.persona.brain.persona.Personaimport com.roshan.persona.brain.persona.ResponseStyleimport com.roshan.persona.brain.persona.Toneimport com.roshan.persona.brain.skill.SkillOutputimport com.roshan.persona.brain.trace.BrainTraceimport com.roshan.persona.common.CorrelationIdimport timber.log.Timberimport java.time.Instantimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Brain Post-Processor. * * Final stage of the brain pipeline. Takes the skill output from the layer * cascade and produces the final [BrainResponse] shown to the user. * * ## Responsibilities * *   1. **Persona styling** — apply tone/emoji/verbosity to **non-LLM** responses *      (L1 rule, L2 skill). LLM responses (L3/L4) are already styled via *      prompt injection in [ContextInjector]. *   2. **Spoken message generation** — strip emoji, simplify for TTS *      (LLM streamed text → TTS engine handles; non-LLM → post-processor generates) *   3. **Memory store** — persist episodic memory of this interaction *   4. **Audit log finalize** — persist [BrainTrace] to Room *   5. **Suggestion generation** — actionable next-steps for the user *   6. **Response assembly** — build final [BrainResponse] * * ## Why Post-Process? * * Centralizing post-processing ensures: *   - Consistent persona voice across all response types *   - Every interaction is logged for audit + memory *   - Suggestions are context-aware (knows which layer handled it) *   - TTS gets a clean spoken version * * @see <a href="docs/spec/module2-spec-review.pdf">§10.3 Post-Processor</a> */@Singletonclass BrainPostProcessor @Inject constructor(    private val memoryInterface: MemoryInterface?,    private val auditLogPersistence: AuditLogPersistence? = null,) {    /**     * Post-process the [skillOutput] from the layer cascade into a final [BrainResponse].     *     * @param context the brain context (from pre-processor)     * @param cleanInput the cleaned user input (from pre-processor)     * @param skillOutput the output from whichever layer handled the request     * @param trace the full brain trace (all layer decisions)     * @param handledBy which layer produced the response     * @param wasStreamed whether tokens were streamed to UI     * @param costUsd total USD cost of this request     * @param tokensGenerated total LLM tokens generated     * @param warnings additional warnings to surface to user     * @return final [BrainResponse] ready for UI     */    suspend fun process(        context: BrainContext,        cleanInput: String,        skillOutput: SkillOutput,        trace: BrainTrace,        handledBy: BrainLayer,        wasStreamed: Boolean,        costUsd: Float,        tokensGenerated: Int,        warnings: List<String> = emptyList(),    ): BrainResponse {        val startNanos = System.nanoTime()        // ─── 1. Extract message + status from skill output ───────────────        val (rawMessage, status, userWarnings) = extractMessageAndStatus(skillOutput, warnings)        // ─── 2. Apply persona styling (non-LLM only) ──────────────────────        val styledMessage = if (shouldStyleResponse(handledBy)) {            applyPersonaStyle(rawMessage, context.activePersona)        } else {            rawMessage  // LLM already styled via prompt        }        // ─── 3. Generate spoken message ──────────────────────────────────        val spokenMessage = if (shouldStyleResponse(handledBy)) {            generateSpokenMessage(styledMessage)        } else {            null  // LLM streamed text → TTS engine handles        }        // ─── 4. Store memory (episodic) ──────────────────────────────────        storeMemory(context, cleanInput, styledMessage, handledBy)        // ─── 5. Persist audit log ────────────────────────────────────────        persistAuditLog(trace)        // ─── 6. Generate suggestions ─────────────────────────────────────        val suggestions = generateSuggestions(skillOutput, handledBy, context)        // ─── 7. Assemble final response ──────────────────────────────────        val now = Instant.now()        val durationMs = (System.nanoTime() - startNanos) / 1_000_000        Timber.tag("NOUS.Post").v(            "Post-processed in %dms (layer=%s, status=%s, suggestions=%d)",            durationMs, handledBy.displayName, status, suggestions.size,        )        return BrainResponse(            correlationId = context.correlationId,            sessionId = context.sessionId,            receivedAt = context.timestamp,            completedAt = now,            totalDurationMs = now.toEpochMilli() - context.timestamp.toEpochMilli(),            message = styledMessage,            spokenMessage = spokenMessage,            trace = trace,            handledBy = handledBy,            status = status,            costUsd = costUsd,            tokensGenerated = tokensGenerated,            suggestions = suggestions,            wasStreamed = wasStreamed,            warnings = userWarnings,        )    }    // ─── Internal helpers ────────────────────────────────────────────────    /**     * Extract the message text, status, and warnings from [SkillOutput].     */    private fun extractMessageAndStatus(        skillOutput: SkillOutput,        extraWarnings: List<String>,    ): Triple<String, BrainResponseStatus, List<String>> {        return when (skillOutput) {            is SkillOutput.Success -> Triple(                skillOutput.message,                BrainResponseStatus.SUCCESS,                extraWarnings,            )            is SkillOutput.Partial -> Triple(                skillOutput.message,                BrainResponseStatus.PARTIAL,                extraWarnings + skillOutput.warnings,            )            is SkillOutput.Failure -> Triple(                skillOutput.userMessage ?: "I couldn't complete that request.",                BrainResponseStatus.FAILURE,                extraWarnings,            )            is SkillOutput.NeedsInput -> Triple(                skillOutput.prompt,                BrainResponseStatus.NEEDS_INPUT,                extraWarnings,            )            is SkillOutput.NeedsPermission -> Triple(                skillOutput.userMessage,                BrainResponseStatus.NEEDS_PERMISSION,                extraWarnings,            )        }    }    /**     * Whether to apply persona styling to this response.     *     * LLM responses (L3/L4/L5) are already styled via prompt injection.     * Non-LLM responses (L1 rule, L2 skill) need post-process styling.     */    private fun shouldStyleResponse(handledBy: BrainLayer): Boolean {        return handledBy == BrainLayer.RULE ||            handledBy == BrainLayer.SKILL ||            handledBy == BrainLayer.INTENT ||            handledBy == BrainLayer.NONE    }    /**     * Apply persona voice styling to a non-LLM response.     *     * Examples:     *   - JARVIS (witty): "Torch on" → "Torch on, sir. ⚡"     *   - FRIDAY (warm): "Torch on" → "Torch on! ✨"     *   - ULTRON (cold): "Torch on" → "Torch: activated."     */    private fun applyPersonaStyle(message: String, persona: Persona): String {        val style = persona.responseStyle        val styled = StringBuilder(message)        // Apply tone-based prefix (only for short responses)        if (message.length < 50 && !message.endsWith("!") && !message.endsWith(".")) {            when (style.tone) {                Tone.WITTY -> styled.append(", sir.")                Tone.WARM -> styled.append("!")                Tone.COLD -> styled.append(".")                Tone.GENTLE -> styled.append(".")                Tone.TACTICAL -> styled.append(".")                Tone.FORMAL -> styled.append(".")                Tone.CALM -> styled.append(".")                Tone.FRIENDLY -> styled.append("!")            }        }        // Apply emoji (if persona uses them)        if (style.useEmoji && message.length < 100) {            val emoji = pickEmojiForMessage(message, persona)            if (emoji != null) {                styled.append(" ").append(emoji)            }        }        // Apply verbosity (for terse personas, truncate long messages)        val result = styled.toString()        return when (style.verbosity) {            com.roshan.persona.brain.persona.Verbosity.TERSE -> {                if (result.length > 200) result.take(197) + "..." else result            }            else -> result        }    }    /**     * Pick an emoji appropriate for the message + persona.     */    private fun pickEmojiForMessage(message: String, persona: Persona): String? {        val lower = message.lowercase()        return when {            lower.contains("torch") || lower.contains("light") -> "🔦"            lower.contains("call") -> "📞"            lower.contains("sms") || lower.contains("message") -> "💬"            lower.contains("alarm") || lower.contains("timer") -> "⏰"            lower.contains("volume") || lower.contains("mute") -> "🔊"            lower.contains("error") || lower.contains("fail") -> "⚠️"            lower.contains("success") || lower.contains("done") || lower.contains("ok") -> "✅"            else -> null        }    }    /**     * Generate TTS-friendly spoken message (strip emoji, simplify).     */    private fun generateSpokenMessage(message: String): String {        return message            .replace(Regex("[\\p{So}\\p{Sk}\\p{Sc}]"), "")  // strip emoji/symbols            .replace(Regex("\\s+"), " ")            .trim()    }    /**     * Store episodic memory of this interaction.     *     * Real impl writes to Room (episodic_memories table) with embedding     * for semantic recall. For Module 2, calls [MemoryInterface.store].     */    private suspend fun storeMemory(        context: BrainContext,        userInput: String,        brainResponse: String,        handledBy: BrainLayer,    ) {        if (memoryInterface == null) return        val memory = Memory(            type = MemoryType.EPISODIC,            content = "User: $userInput\nNOUS: $brainResponse",            timestamp = Instant.now(),            importance = computeImportance(handledBy, brainResponse),            tags = setOf(handledBy.displayName.lowercase(), "interaction"),            correlationId = context.correlationId,            sessionId = context.sessionId,        )        try {            val result = memoryInterface.store(memory)            if (result is com.roshan.persona.common.Result.Failure) {                Timber.tag("NOUS.Post").w("Memory store failed: ${result.error.message}")            }        } catch (t: Throwable) {            Timber.tag("NOUS.Post").w(t, "Memory store crashed (non-fatal)")        }    }    /**     * Compute importance score (0.0-1.0) for this memory.     *     * LLM responses are more important than rule fires (worth remembering).     */    private fun computeImportance(handledBy: BrainLayer, response: String): Float {        return when (handledBy) {            BrainLayer.RULE -> 0.1f  // trivial            BrainLayer.SKILL -> 0.3f  // action taken            BrainLayer.LOCAL_LLM, BrainLayer.CLOUD_LLM -> 0.7f  // knowledge            BrainLayer.AGENTIC -> 0.9f  // complex multi-step            else -> 0.2f        }    }    /**     * Persist the brain trace to audit log.     */    private suspend fun persistAuditLog(trace: BrainTrace) {        if (auditLogPersistence == null) return        try {            auditLogPersistence.persist(trace)        } catch (t: Throwable) {            Timber.tag("NOUS.Post").w(t, "Audit log persist failed (non-fatal)")        }    }    /**     * Generate actionable suggestions based on the response.     */    private fun generateSuggestions(        skillOutput: SkillOutput,        handledBy: BrainLayer,        context: BrainContext,    ): List<BrainSuggestion> {        val suggestions = mutableListOf<BrainSuggestion>()        when (skillOutput) {            is SkillOutput.Failure -> {                // Suggest enabling cloud if local failed                if (handledBy == BrainLayer.LOCAL_LLM && !context.userContext.privacySettings.cloudLlmEnabled) {                    suggestions.add(BrainSuggestion(                        text = "Enable cloud AI for better responses",                        type = SuggestionType.ENABLE_CLOUD,                        deepLink = "nous://settings/privacy",                        actionLabel = "Enable",                    ))                }                // Suggest downloading a model if local failed                if (handledBy == BrainLayer.LOCAL_LLM) {                    suggestions.add(BrainSuggestion(                        text = "Download a local AI model",                        type = SuggestionType.DOWNLOAD_MODEL,                        deepLink = "nous://settings/ai-models",                        actionLabel = "Download",                    ))                }            }            is SkillOutput.NeedsPermission -> {                suggestions.add(BrainSuggestion(                    text = "Grant ${skillOutput.missingPermissions.firstOrNull() ?: "permission"} to continue",                    type = SuggestionType.GRANT_PERMISSION,                    actionLabel = "Grant",                ))            }            is SkillOutput.Partial -> {                suggestions.add(BrainSuggestion(                    text = "Try rephrasing for a better response",                    type = SuggestionType.REPHRASE,                ))            }            else -> { /* no suggestions for success */ }        }        return suggestions    }}/** * Audit log persistence interface (real impl in Module 3 via Room). */fun interface AuditLogPersistence {    suspend fun persist(trace: BrainTrace)}